#!/bin/zsh
# Step 3 critiques: Gemini Argon (tools/gemini.py ask) + Opus (claude-as), A/B vs the m96 master. -> crit/*.txt
E=${0:A:h:h}; SW=/Users/waylonhuang/Documents/other/pixelart/swordswoman; mkdir -p $E/crit
B=$E/boards
P_SE="You are a strict pixel-art director. The board shows, left to right: the approved design illustration; our APPROVED 96 px pixel master (4x and 1x; the user accepted it, critics gave it about 6-7/10); then four NEW candidates a1, a1b, a2, a2b, each as [raw Gemini 'pixel art' output, our version after grid recovery + downscale to the same 96 px figure + palette lock at 4x, and 1x]. Judge ONLY the locked 4x/1x versions. For each candidate give A/B vs the master: is it better or worse pixel art (clusters, outline, jaggies, banding, orphan pixels, readable face at 1x) and is it more or less faithful to the illustration (bow, bob with bun, face/eyes, kimono, obi, socks, boots, proportions)? Score master and each candidate 1-10 on (identity, pixel quality, face at 1x) using the master as the anchor. List 3 concrete pixel problems per candidate with locations. Do not inflate; say plainly if a candidate is worse than the master. End with one line: BEST=<name or master>."
P_POSE="You are a strict animation and pixel-art director. Image 1 is a consistency board: the approved 96 px master (left) followed by 4 key poses (walk, run, jump, throw) made by two different methods: row (b) = Gemini asked directly for pixel art in the pose, then our grid recovery + palette lock; row (c) = Gemini asked for an anime illustration in the pose, then our deterministic pixelizer (E2, the same one that made the master). Both rows at 4x and 1x, same pixel scale (head size matched to the master). Image 2 shows the guides and raw Gemini images for every sample. Questions: (1) Does each row stay ON-MODEL vs the master across poses: red bow, dark bob + bun, red short kimono with wide sleeves, grey-lavender obi, eye style, palette, head-to-body proportion? List every deviation per pose. (2) Pixel quality per pose vs the master (clusters, outline, noise, readability at 1x). (3) Score each pose 1-10 as an animation KEY usable after light hand cleanup, master = anchor. (4) Which row is the better basis for animation keys and why? Be concrete and do not inflate. End with one line: BETTER_ROW=<b|c>."
cd $SW
.venv/bin/python tools/gemini.py ask "$P_SE" $B/b2_SE.png > $E/crit/argon_SE.txt 2>&1 &
.venv/bin/python tools/gemini.py ask "$P_POSE" $B/b4_consistency_hn.png $B/b3_poses_hn.png > $E/crit/argon_poses.txt 2>&1 &
zsh -ic "claude-as be_system --dangerously-skip-permissions --model claude-opus-5-5 -p \"Read the image $B/b2_SE.png (use the Read tool; zoom by reading it, it is a PNG). $P_SE\"" > $E/crit/opus_SE.txt 2>&1 &
zsh -ic "claude-as be_system --dangerously-skip-permissions --model claude-opus-5-5 -p \"Read image 1 $B/b4_consistency_hn.png and image 2 $B/b3_poses_hn.png with the Read tool. $P_POSE\"" > $E/crit/opus_poses.txt 2>&1 &
wait
for f in $E/crit/*.txt; do echo "$f $(wc -c < $f)"; done
